<?php

namespace Modules\Sales\Controllers;

use Modules\Authentication\Middleware\AuthMiddleware;
use Modules\Authentication\Models\User;
use Modules\Authentication\Support\Request;
use Modules\Sales\Repositories\SalesRepository;

final class SalesController
{
    public function __construct(private SalesRepository $sales = new SalesRepository()) {}
    private function auth(): array { return AuthMiddleware::handle(); }
    private function fail(array $auth): array { return ['success'=>false,'message'=>$auth['error'],'status'=>$auth['status']]; }
    public function leads(array $params): array { $a=$this->auth(); if(isset($a['error'])) return $this->fail($a); $filters=$this->scopedFilters(Request::all(),$a['user']); return ['success'=>true,'data'=>$this->sales->leads($filters)]; }
    public function storeLead(array $params): array { $a=$this->auth(); if(isset($a['error'])) return $this->fail($a); if(!$this->canWriteLeads($a['user'])) return $this->forbidden(); $d=Request::all(); $validation=$this->validateLead($d,true); if($validation) return $validation; $id=$this->employeeId($a['user']); if(!$id) return ['success'=>false,'message'=>'Authenticated user is not linked to an employee.','status'=>422]; $requested=(string)($d['assigned_employee_id']??''); if($requested && !$this->canManageEmployee($a['user'],$requested)) return $this->forbidden('You can assign leads only to yourself or your sales team.'); if($this->isExecutive($a['user'])) $d['assigned_employee_id']=$id; try{return ['success'=>true,'data'=>$this->sales->createLead($d,$id),'status'=>201];}catch(\Throwable){return ['success'=>false,'message'=>'Unable to create lead. Check the selected employee and lead data.','status'=>422];} }
    public function updateLead(array $params): array { $a=$this->auth(); if(isset($a['error'])) return $this->fail($a); if(!$this->canWriteLeads($a['user'])) return $this->forbidden(); $lead=$this->sales->findLead($params['id']); if(!$lead) return ['success'=>false,'message'=>'Lead not found.','status'=>404]; if(!$this->canManageEmployee($a['user'],(string)$lead['assigned_employee_id'])) return $this->forbidden('You can update only your own or your team\'s leads.'); $d=Request::all(); $validation=$this->validateLead($d,false); if($validation) return $validation; if(isset($d['assigned_employee_id'])&&!$this->canManageEmployee($a['user'],(string)$d['assigned_employee_id'])) return $this->forbidden('You can assign leads only to yourself or your sales team.'); try{$row=$this->sales->updateLead($params['id'],$d,$this->employeeId($a['user'])); return ['success'=>true,'data'=>$row];}catch(\Throwable){return ['success'=>false,'message'=>'Unable to update lead.','status'=>422];} }
    public function activities(array $params): array { $a=$this->auth(); if(isset($a['error'])) return $this->fail($a); if(!$this->canWriteLeads($a['user'])) return $this->forbidden(); $lead=$this->sales->findLead($params['id']); if(!$lead) return ['success'=>false,'message'=>'Lead not found.','status'=>404]; if(!$this->canManageEmployee($a['user'],(string)$lead['assigned_employee_id'])) return $this->forbidden('You can add notes only to your own or your team\'s leads.'); $d=Request::all(); $note=trim((string)($d['note']??'')); if($note===''||strlen($note)>2000) return ['success'=>false,'message'=>'Note is required and must be at most 2000 characters.','status'=>422]; return ['success'=>true,'data'=>$this->sales->addActivity($params['id'],$d['type']??'Note',$note,$this->employeeId($a['user'])),'status'=>201]; }
    public function dashboard(array $params): array { $a=$this->auth(); if(isset($a['error'])) return $this->fail($a); return ['success'=>true,'data'=>$this->sales->dashboard($this->scopeEmployeeIds($a['user']))]; }
    public function orders(array $params): array { $a=$this->auth(); if(isset($a['error'])) return $this->fail($a); return ['success'=>true,'data'=>$this->sales->orders($this->scopeEmployeeIds($a['user']))]; }
    public function updateOrderStatus(array $params): array { $a=$this->auth(); if(isset($a['error'])) return $this->fail($a); if(!$this->canWriteLeads($a['user'])) return $this->forbidden('Only sales operations users can update an order status.'); $order=$this->sales->findOrder($params['id']); if(!$order) return ['success'=>false,'message'=>'Order not found.','status'=>404]; if(!$this->canManageEmployee($a['user'],(string)$order['employee_id'])) return $this->forbidden('You can update only your own or your team\'s orders.'); $status=(string)(Request::all()['order_status']??''); if(!in_array($status,['Pending','Confirmed','Packed','Dispatched','Delivered','Cancelled'],true)) return ['success'=>false,'message'=>'Order status is invalid.','status'=>422]; $updated=$this->sales->updateOrderStatus($params['id'],$status); return ['success'=>true,'data'=>$updated,'message'=>'Order status updated.']; }
    public function territories(array $params): array { $a=$this->auth(); if(isset($a['error'])) return $this->fail($a); return ['success'=>true,'data'=>$this->sales->territories()]; }
    public function targets(array $params): array { $a=$this->auth(); if(isset($a['error'])) return $this->fail($a); return ['success'=>true,'data'=>$this->sales->targets($this->scopeEmployeeIds($a['user']))]; }
    public function storeTarget(array $params): array { $a=$this->auth(); if(isset($a['error'])) return $this->fail($a); if(!$this->canSetTargets($a['user'])) return $this->forbidden('Only Admin or ASM can assign sales targets.'); $d=Request::all(); if ((float)($d['target_value']??0) <= 0 || !is_numeric($d['target_value'])) return ['success'=>false,'message'=>'Target value must be greater than zero.','status'=>422]; if(isset($d['period_start'],$d['period_end'])&&$d['period_end']<$d['period_start']) return ['success'=>false,'message'=>'Target end date cannot be before start date.','status'=>422]; $assigned=(string)($d['assigned_to_employee_id']??''); if(!$assigned||!$this->canManageEmployee($a['user'],$assigned)) return $this->forbidden('You can assign targets only to your sales team.'); try{return ['success'=>true,'data'=>$this->sales->createTarget($d,$this->employeeId($a['user'])),'status'=>201];}catch(\Throwable){return ['success'=>false,'message'=>'Unable to create target. Check employee and target data.','status'=>422];} }
    public function updateTarget(array $params): array { $a=$this->auth(); if(isset($a['error'])) return $this->fail($a); if(!$this->canSetTargets($a['user'])) return $this->forbidden('Only Admin or ASM can update sales targets.'); $target=$this->sales->findTarget($params['id']); if(!$target) return ['success'=>false,'message'=>'Target not found.','status'=>404]; if(!$this->canManageEmployee($a['user'],(string)$target['assigned_to_employee_id'])) return $this->forbidden('You can update targets only for your sales team.'); $d=Request::all(); if ((float)($d['target_value']??0) <= 0 || !is_numeric($d['target_value'])) return ['success'=>false,'message'=>'Target value must be greater than zero.','status'=>422]; return ['success'=>true,'data'=>$this->sales->updateTarget($params['id'],(float)$d['target_value'],$d['remarks']??null),'message'=>'Target updated.']; }
    public function visits(array $params): array { $a=$this->auth(); if(isset($a['error'])) return $this->fail($a); return ['success'=>true,'data'=>$this->sales->visits($this->scopeEmployeeIds($a['user']))]; }
    public function expenses(array $params): array { $a=$this->auth(); if(isset($a['error'])) return $this->fail($a); return ['success'=>true,'data'=>$this->sales->expenses($this->scopeEmployeeIds($a['user']))]; }
    public function reports(array $params): array { $a=$this->auth(); if(isset($a['error'])) return $this->fail($a); return ['success'=>true,'data'=>$this->sales->reports($this->scopeEmployeeIds($a['user']))]; }
    public function updateReportFeedback(array $params): array { $a=$this->auth(); if(isset($a['error'])) return $this->fail($a); if(!$this->isAdmin($a['user'])&&!$this->isAsm($a['user'])) return $this->forbidden('Only Admin or ASM can provide sales feedback.'); $report=$this->sales->findReport($params['id']); if(!$report) return ['success'=>false,'message'=>'Daily report not found.','status'=>404]; if(!$this->canManageEmployee($a['user'],(string)$report['employee_id'])) return $this->forbidden('You can provide feedback only to your sales team.'); $feedback=trim((string)(Request::all()['feedback']??'')); if($feedback===''||strlen($feedback)>2000) return ['success'=>false,'message'=>'Feedback is required and must be at most 2000 characters.','status'=>422]; return ['success'=>true,'data'=>$this->sales->updateReportFeedback($params['id'],$feedback,$this->employeeId($a['user'])),'message'=>'Feedback saved.']; }
    public function assignOrderTerritory(array $params): array { $a=$this->auth(); if(isset($a['error'])) return $this->fail($a); if(!$this->isAdmin($a['user'])&&!$this->isAsm($a['user'])) return $this->forbidden('Only Admin or ASM can assign an order territory.'); $order=$this->sales->findOrder($params['id']); if(!$order) return ['success'=>false,'message'=>'Order not found.','status'=>404]; if(!$this->canManageEmployee($a['user'],(string)$order['employee_id'])) return $this->forbidden('You can assign territories only for your sales team.'); $territory=trim((string)(Request::all()['territory']??'')); if($territory==='') return ['success'=>false,'message'=>'Territory is required.','status'=>422]; $ok=$this->sales->assignOrderTerritory($params['id'],$territory); return $ok?['success'=>true,'message'=>'Territory updated.']:['success'=>false,'message'=>'Territory not found.','status'=>404]; }
    private function isExecutive(array $user): bool { return in_array(strtoupper((string)($user['role']??'')), ['SE','SALES_EXECUTIVE','SALES EXECUTIVE'], true); }
    private function isAdmin(array $user): bool { return strtoupper((string)($user['role']??'')) === 'ADMIN'; }
    private function isAsm(array $user): bool { return strtoupper((string)($user['role']??'')) === 'ASM'; }
    private function employeeId(array $user): string { return (string)($user['employee_id'] ?? $this->sales->employeeIdByEmail((string)($user['email'] ?? '')) ?? ''); }
    private function forbidden(string $message='You do not have permission to perform this action.'): array { return ['success'=>false,'message'=>$message,'status'=>403]; }
    private function canWriteLeads(array $user): bool { return $this->isAdmin($user)||$this->isAsm($user)||$this->isExecutive($user); }
    private function canSetTargets(array $user): bool { return $this->isAdmin($user)||$this->isAsm($user); }
    private function scopeEmployeeIds(array $user): ?array { if($this->isAdmin($user)||strtoupper((string)($user['role']??''))==='HR') return null; return $this->sales->teamEmployeeIds($this->employeeId($user),$this->isAsm($user)); }
    private function scopedFilters(array $filters,array $user): array { $ids=$this->scopeEmployeeIds($user); if($ids!==null){$filters['employee_ids']=$ids; unset($filters['employee_id']);} return $filters; }
    private function canManageEmployee(array $user,string $employeeId): bool { if($this->isAdmin($user)) return true; return in_array($employeeId,$this->scopeEmployeeIds($user)??[],true); }
    private function validateLead(array $data,bool $creating): ?array { $allowedSegments=['B2B','B2C'];$allowedStatuses=['New','New Lead','Contacted','Proposal Sent','In Negotiation','Converted','Closed','Archived']; if($creating){foreach(['segment','lead_name','phone_number'] as $field)if(trim((string)($data[$field]??''))==='')return ['success'=>false,'message'=>"$field is required.",'status'=>422];} if(isset($data['segment'])&&!in_array($data['segment'],$allowedSegments,true))return ['success'=>false,'message'=>'Segment must be B2B or B2C.','status'=>422];if(isset($data['current_status'])&&!in_array($data['current_status'],$allowedStatuses,true))return ['success'=>false,'message'=>'Lead status is invalid.','status'=>422];if(isset($data['email'])&&$data['email']!==''&&!filter_var($data['email'],FILTER_VALIDATE_EMAIL))return ['success'=>false,'message'=>'A valid email is required.','status'=>422];if(isset($data['estimated_value'])&&(!is_numeric($data['estimated_value'])||(float)$data['estimated_value']<0))return ['success'=>false,'message'=>'Estimated value must be zero or greater.','status'=>422];return null; }
}
